package com.mo.economy_system.common.territory;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
class TerritoryInviteDecisionServiceTest{private record Fixture(TerritoryInviteStore store,TerritoryInvite invite){}private static Fixture fixture(){TerritoryInviteStore s=new TerritoryInviteStore();UUID owner=UUID.randomUUID(),target=UUID.randomUUID();TerritoryInvite i=new TerritoryInvite(UUID.randomUUID(),UUID.randomUUID(),owner,owner,target,"land","owner","target",0,1200);s.put(i,0);return new Fixture(s,i);}@Test void acceptConsumesAndWritesOnce(){Fixture f=fixture();AtomicInteger writes=new AtomicInteger();TerritoryInviteDecisionService d=new TerritoryInviteDecisionService(f.store,(a,b,c,e)->{writes.incrementAndGet();return TerritoryInviteDecisionService.WriteResult.ADDED;});assertEquals(TerritoryInviteDecisionService.Result.ACCEPTED,d.accept(f.invite.inviteId(),f.invite.targetPlayerId(),"target",1));assertEquals(TerritoryInviteDecisionService.Result.NOT_FOUND,d.accept(f.invite.inviteId(),f.invite.targetPlayerId(),"target",1));assertEquals(1,writes.get());}@Test void declineNeverWritesAndOnlyTargetDecides(){Fixture f=fixture();AtomicInteger writes=new AtomicInteger();TerritoryInviteDecisionService d=new TerritoryInviteDecisionService(f.store,(a,b,c,e)->{writes.incrementAndGet();return TerritoryInviteDecisionService.WriteResult.ADDED;});assertEquals(TerritoryInviteDecisionService.Result.NOT_TARGET,d.decline(f.invite.inviteId(),UUID.randomUUID(),1));assertEquals(TerritoryInviteDecisionService.Result.DECLINED,d.decline(f.invite.inviteId(),f.invite.targetPlayerId(),1));assertEquals(0,writes.get());}@Test void persistentFailureReleasesForRetry(){Fixture f=fixture();AtomicInteger writes=new AtomicInteger();TerritoryInviteDecisionService d=new TerritoryInviteDecisionService(f.store,(a,b,c,e)->writes.getAndIncrement()==0?TerritoryInviteDecisionService.WriteResult.PERSIST_FAILED:TerritoryInviteDecisionService.WriteResult.ADDED);assertEquals(TerritoryInviteDecisionService.Result.PERSIST_FAILED,d.accept(f.invite.inviteId(),f.invite.targetPlayerId(),"target",1));assertEquals(TerritoryInviteDecisionService.Result.ACCEPTED,d.accept(f.invite.inviteId(),f.invite.targetPlayerId(),"target",2));}}
